PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE authors (
  id            TEXT PRIMARY KEY,   
  full_name     TEXT NOT NULL,
  orcid         TEXT,
  created_at    TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at    TEXT DEFAULT CURRENT_TIMESTAMP
, verified_internal INTEGER);
CREATE TABLE publications (
  id                TEXT PRIMARY KEY,   
  title             TEXT NOT NULL,
  doi               TEXT,
  cover_date        TEXT,
  year              INTEGER NOT NULL,
  document_type     TEXT,
  source_title      TEXT,
  cited_by_count    INTEGER DEFAULT 0,
  raw_json          TEXT,
  created_at        TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at        TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE publication_authors (
  publication_id  TEXT NOT NULL REFERENCES publications(id),
  author_id       TEXT NOT NULL REFERENCES authors(id),
  author_order    INTEGER,
  is_internal     INTEGER NOT NULL,
  PRIMARY KEY (publication_id, author_id)
);
CREATE TABLE sync_runs (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  started_at          TEXT NOT NULL,
  finished_at         TEXT,
  publications_synced INTEGER,
  status              TEXT,
  error_message       TEXT
);
CREATE TABLE publication_subject_areas (
  publication_id  TEXT NOT NULL REFERENCES publications(id),
  code            TEXT NOT NULL,
  abbrev          TEXT,
  name            TEXT NOT NULL,
  PRIMARY KEY (publication_id, code)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_publications_year ON publications(year);
CREATE INDEX idx_pub_authors_author ON publication_authors(author_id);
CREATE INDEX idx_pub_subject_areas_name ON publication_subject_areas(name);